export.example:

// Basic initialization
await ghosttrace.init({
  adminEmail: 'admin@company.com',
  adminPassword: 'SecurePass123!',
});

// Full configuration
const instance = await ghosttrace.init({
  adminEmail: process.env.GHOST_ADMIN_EMAIL,
  adminPassword: process.env.GHOST_ADMIN_PASS,
  dashboardPort: 4001,
  blockThreshold: 80,
  rateLimit: 100,
  database: {
    type: 'postgres',
    host: 'localhost',
    port: 5432,
    name: 'myapp_security',
    user: 'postgres',
    password: 'dbpass',
  },
  ai: {
    provider: 'openai',
    apiKey: process.env.OPENAI_API_KEY,
  },
});

// Later: stop GhostTrace
await instance.stop();

example.code:

// Protect all API routes
app.use('/api', ghosttrace.secure());

app.get('/api/users', (req, res) => {
  res.json({ users: [] });
});


// High security for authentication
app.use('/api/auth', ghosttrace.secure({ 
  riskThreshold: 60,
  rateLimit: 30,
}));

// Standard for posts
app.use('/api/posts', ghosttrace.secure({ 
  riskThreshold: 70,
}));

// Monitor only for public endpoints
app.use('/api/public', ghosttrace.secure({ 
  blockOnThreat: false,
}));


app.use('/api/critical', ghosttrace.secure({
  riskThreshold: 50,
  onThreat: async (req, res, analysis) => {
    // Log to external SIEM
    await logToSIEM(analysis);

    // Send custom response
    res.status(403).json({
      error: 'Access denied',
      contactSupport: 'security@company.com',
    });
  },
}));


app.use('/api', ghosttrace.secure({
  identifyUser: (req) => ({
    userId: req.user?.id || 'anonymous',
    accountId: req.headers['x-tenant-id'] || 'default',
  }),
}));

