app.get('/api/profile', ghosttrace.secure(), (req, res) => {
  // Access GhostTrace data
  console.log('Client DNA:', req.clientDNA);
  console.log('Risk Score:', req.protectionAnalysis?.riskScore);
  console.log('Is Threat:', req.protectionAnalysis?.isThreat);

  // Use in business logic
  if (req.protectionAnalysis?.riskScore > 80) {
    // Require additional verification
    return res.json({ requireMFA: true });
  }

  res.json({ profile: userProfile });
});

