example.code:

require('dotenv').config();
const express = require('express');
const ghosttrace = require('ghosttrace');

const app = express();
app.use(express.json());

// Initialize GhostTrace
(async () => {
  await ghosttrace.init({
    adminEmail: process.env.GHOST_ADMIN_EMAIL,
    adminPassword: process.env.GHOST_ADMIN_PASS,
  });

  // Protect all API routes
  app.use('/api', ghosttrace.secure());

  // Your routes
  app.get('/api/hello', (req, res) => {
    res.json({ message: 'Hello, World!' });
  });

  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
})();


const express = require('express');
const ghosttrace = require('ghosttrace');

const app = express();

(async () => {
  await ghosttrace.init({
    adminEmail: process.env.GHOST_ADMIN_EMAIL,
    adminPassword: process.env.GHOST_ADMIN_PASS,
    dashboardPort: 3001,
    blockThreshold: 70,
  });

  // Extra protection for authentication (lower threshold)
  app.use('/api/auth', ghosttrace.secure({ 
    riskThreshold: 60,
    rateLimit: 30,  // Stricter rate limit
  }));

  // Standard protection for user operations
  app.use('/api/users', ghosttrace.secure({ 
    riskThreshold: 70,
  }));

  // Standard for posts
  app.use('/api/posts', ghosttrace.secure({ 
    riskThreshold: 70,
  }));

  // Monitor only for public feed (don't block users)
  app.use('/api/feed', ghosttrace.secure({ 
    blockOnThreat: false,
  }));

  // Authentication routes
  app.post('/api/auth/register', registerHandler);
  app.post('/api/auth/login', loginHandler);

  // User routes
  app.get('/api/users/:id', getUserHandler);
  app.put('/api/users/:id', updateUserHandler);

  // Post routes
  app.get('/api/posts', getPostsHandler);
  app.post('/api/posts', createPostHandler);
  app.delete('/api/posts/:id', deletePostHandler);

  // Public feed (no authentication)
  app.get('/api/feed', publicFeedHandler);

  app.listen(3000);
})();


const express = require('express');
const ghosttrace = require('ghosttrace');

const app = express();

(async () => {
  await ghosttrace.init({
    adminEmail: process.env.GHOST_ADMIN_EMAIL,
    adminPassword: process.env.GHOST_ADMIN_PASS,
  });

  // Maximum security for payment processing
  app.use('/api/payments', ghosttrace.secure({ 
    riskThreshold: 40,  // Very sensitive
    rateLimit: 20,
  }));

  // High security for checkout
  app.use('/api/checkout', ghosttrace.secure({ 
    riskThreshold: 50,
    rateLimit: 30,
  }));

  // Standard for cart
  app.use('/api/cart', ghosttrace.secure({ 
    riskThreshold: 70,
  }));

  // Low security for product browsing
  app.use('/api/products', ghosttrace.secure({ 
    riskThreshold: 90,
    blockOnThreat: false,  // Don't block browsers
  }));

  app.post('/api/checkout', checkoutHandler);
  app.post('/api/payments/process', paymentHandler);
  app.get('/api/cart', getCartHandler);
  app.get('/api/products', getProductsHandler);

  app.listen(3000);
})();


