const ghosttrace = require('ghosttrace');
const siemLogger = require('./siem-logger');

await ghosttrace.init({
  adminEmail: process.env.GHOST_ADMIN_EMAIL,
  adminPassword: process.env.GHOST_ADMIN_PASS,
});

app.use('/api', ghosttrace.secure({
  onThreat: async (req, res, analysis) => {
    // Log to external SIEM
    await siemLogger.logThreat({
      timestamp: new Date(),
      ip: req.ip,
      endpoint: req.path,
      riskScore: analysis.riskScore,
      anomalies: analysis.anomalies,
      dna: req.clientDNA,
    });

    // Trigger incident response workflow
    if (analysis.riskScore > 90) {
      await incidentResponse.createTicket({
        severity: 'critical',
        source: 'ghosttrace',
        details: analysis,
      });
    }

    // Send custom response
    res.status(403).json({
      error: 'Security violation detected',
      ticketId: 'INC-12345',
      contact: 'security@company.com',
    });
  },
}));


const jwt = require('jsonwebtoken');
const ghosttrace = require('ghosttrace');

await ghosttrace.init({
  adminEmail: process.env.GHOST_ADMIN_EMAIL,
  adminPassword: process.env.GHOST_ADMIN_PASS,
});

app.use('/api', ghosttrace.secure({
  identifyUser: (req) => {
    // Extract from JWT
    const token = req.headers.authorization?.split(' ')[1];
    if (token) {
      try {
        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        return {
          userId: decoded.userId,
          accountId: decoded.tenantId,
        };
      } catch (err) {
        // Invalid token
      }
    }

    // Fall back to headers
    return {
      userId: req.headers['x-user-id'] || 'anonymous',
      accountId: req.headers['x-tenant-id'] || 'default',
    };
  },
}));

